{
  "premises": [
    {
      "statement": "Candidate insights without matching applications, and applications without matching postings, must remain in the candidate quality summary.",
      "about": "requirement",
      "target": "marts.lever__candidate_quality_insights",
      "evidence_of_dependence": "FROM intermediate.int_lever__candidate_insights ci LEFT JOIN staging.stg_lever__application a USING(opportunity_id) LEFT JOIN staging.stg_lever__posting p USING(posting_id)",
      "alternative": "The contract says \"Join candidate insights to applications on opportunity_id, then to postings on posting_id\" without specifying left joins; inner joins would exclude unmatched records.",
      "importance": 4,
      "reason": "Retaining unmatched records changes the analyzed population, source classification, distributions, and recommendations.",
      "updates": null
    },
    {
      "statement": "Applications created after the execution date must be excluded from the hiring dashboard's application and candidate counts.",
      "about": "requirement",
      "target": "marts.lever__hiring_dashboard",
      "evidence_of_dependence": "WHERE created_at>=current_date-INTERVAL '30 days' AND created_at<current_date+INTERVAL '1 day'",
      "alternative": "The contract defines the window as \"on or after 30 calendar days before report_date, inclusive\" and does not specify an upper bound.",
      "importance": 3,
      "reason": "The extra upper bound changes both counts if future-dated applications exist.",
      "updates": null
    },
    {
      "statement": "Each factor's qualifying groups have a unique highest average quality score.",
      "about": "data",
      "target": "marts.lever__candidate_quality_insights",
      "evidence_of_dependence": "row_number() OVER(ORDER BY avg(candidate_quality_score) DESC) rn ... WHERE rn=1",
      "alternative": "The contract warns \"If multiple groups tie for top rank, selecting a single best group is ambiguous and may fail\" and describes ties as unresolved.",
      "importance": 3,
      "reason": "Unverified ties make best-factor selections arbitrary and can change the primary recommendation.",
      "updates": null
    }
  ],
  "fewer": [
    {
      "target": "marts.lever__candidate_quality_insights",
      "count": 2,
      "reason": "The other implemented aggregations and classifications follow the supplied contract; the visible parser failure is not an unestablished data or requirement premise."
    },
    {
      "target": "marts.lever__hiring_dashboard",
      "count": 1,
      "reason": "Apart from the added upper date bound, the joins, distinct counts, snapshot metadata, and lifecycle calculation are explicitly specified."
    },
    {
      "target": "marts.lever__hiring_dashboard_simple",
      "count": 0,
      "reason": "The contract explicitly requires the implemented unfiltered row count and execution-time metadata."
    },
    {
      "target": "marts.lever__hiring_dashboard_working",
      "count": 0,
      "reason": "The implemented join path, lower-bound-only windows, distinct counts, and application-weighted lifecycle average are explicitly documented."
    },
    {
      "target": "marts.lever__recruitment_analytics_dashboard",
      "count": 0,
      "reason": "The implemented distinct counts, fixed health values, and execution-time metadata are explicitly documented."
    }
  ]
}
